const input = $json ?? {};
const event = input.event ?? input;
const dealId = event.deal_id ?? event.dealId;
const leadId = event.lead_id ?? event.leadId;
const propertyId = event.property_id ?? event.propertyId;
const status = String(event.status ?? '').toLowerCase();
const dnc = Boolean(event.dnc ?? event.do_not_contact);
const blockers = Array.isArray(event.blockers) ? event.blockers : [];
const attempts = Number(event.attempts ?? event.outreach_attempts ?? 0);
const maxAttempts = Number(event.max_attempts ?? event.maxOutreachAttempts ?? 3);
const seller = event.seller ?? {};
const phone = event.phone ?? seller.phone;
const email = event.email ?? seller.email;
const followupAt = event.followup_at ?? event.followupAt ?? event.next_followup_at;
const baseKey = event.idempotency_key ?? event.idempotencyKey ?? [dealId, leadId, propertyId, 'seller-followup'].filter(Boolean).join(':');
const idempotencyKey = baseKey + ':followup:' + attempts;
let route = 'WF-352';
let decision = 'blocked';
if (dnc) { route = 'WF-126'; decision = 'dnc_hard_stop'; }
else if (blockers.length) { route = 'WF-126'; decision = 'blocked'; }
else if (!dealId || !leadId || !propertyId || !baseKey) { route = 'WF-352'; decision = 'identity_or_idempotency_missing'; }
else if (!phone && !email) { route = 'WF-352'; decision = 'seller_contact_missing'; }
else if (attempts >= maxAttempts) { route = 'WF-126'; decision = 'human_review_max_attempts'; }
else if (status === 'seller_response' || event.inbound_response) { route = 'WF-342'; decision = 'seller_response'; }
else if (status === 'followup_due' || status === 'follow_up_due' || event.followup_due === true) { route = 'WF-346'; decision = 'followup_due'; }
else { route = 'WF-352'; decision = 'not_due'; }
return [{json:{...event, workflow:'WF-353', decision, route, deal_id:dealId, lead_id:leadId, property_id:propertyId, seller:{...seller, phone, email}, attempts, max_attempts:maxAttempts, followup_at:followupAt, idempotency_key:idempotencyKey, audit_event:'seller_followup_due_controller'}}];
